FUNCTION_BLOCK FB_CMP_InSituEddyCurrentZonalPressure
(*
====================================================================================================
  LUMINA CYBER-PHYSICAL SYSTEMS ARCHITECTURE - HIGH-INTEGRITY AUTOMATION SPECIFICATION
  MODULE:        FB_CMP_InSituEddyCurrentZonalPressure
  SYSTEM:        300mm Semiconductor Chemical Mechanical Planarization (CMP) Equipment
  SUBSYSTEM:     Real-Time In-Situ Eddy Current Film Metrology & Multi-Zone Membrane Control
  SPECIFICATION: IEC 61131-3 Third Edition / IEEE 1451 Sensor Network Compliant
  AUTHOR:        Principal Automation Fellow & Cyber-Physical Systems Chair (V7 Max-Persona)

  THEORETICAL AND PHYSICAL FORMULATION:
  1. Eddy Current Skin-Depth & Sheet Resistance:
     Conductive metal film (Cu/W/Co) thickness is governed by the eddy current skin depth:
       delta = SQRT( 1.0 / (pi * f * mu_0 * mu_r * sigma) )
     Where:
       f     = RF bridge excitation frequency [kHz] (typically 100 kHz to 4000 kHz)
       mu_0  = 4 * pi * 10^-7 H/m (permeability of free space)
       sigma = Electrical conductivity [S/m] (Cu ~ 5.96 * 10^7 S/m at 20 deg C)
     Sheet resistance is inversely proportional to thickness t:
       R_s = rho / t = 1.0 / (sigma * t)
     The high-frequency electromagnetic field induces circular Foucault currents in the film,
     producing a counter-electromotive field that shifts the resonant frequency and reduces
     the real bridge impedance. Signal demodulation yields voltage amplitude V [mV].
     Inverse calibration follows a 3rd-order orthogonal polynomial:
       t(V) = a0 + a1*V + a2*V^2 + a3*V^3 + lift_off_corr(delta_z)

  2. Triple Modular Redundancy (2oo3) Sensor Voting:
     Three independent RF receiver coils / demodulation channels (ChA, ChB, ChC) monitor the
     same wafer radial track. Voting algorithm computes absolute pairwise discrepancies:
       dAB = |tA - tB|, dBC = |tB - tC|, dCA = |tC - tA|
     If max discrepancy < TOL: Median value selected, 0 faults.
     If one channel deviates beyond TOL while remaining two agree: Degraded 2oo2 average used,
     failed channel isolated and flagged.
     If all pairs deviate beyond TOL: Triplicate collapse detected, emergency abort triggered.

  3. Dynamic Multivariable Zonal Model Predictive Control (MPC):
     Wafer removal obeys Preston's law:
       MRR_i(t) = kp * P_i(t) * V_rel_i(t)
     Across 4 discrete concentric pneumatic zones (Z1: Center, Z2: Mid-In, Z3: Mid-Out, Z4: Edge)
     and Retaining Ring (RR). The discrete-time coupled state-space representation is:
       x[k+1] = A_d * x[k] + B_d * u[k] + w[k]
       y[k]   = C_d * x[k]
     Where state x = [e1, e2, e3, e4]^T is the remaining thickness error per zone,
     control vector u = [P1, P2, P3, P4]^T represents pneumatic bladder pressures,
     A_d is diagonal decay matrix (slurry residence dynamics), and B_d is the cross-talk
     pneumatic coupling matrix capturing mechanical membrane tension between adjacent bladders:
       B_d = [ b11  b12   0    0  ]
             [ b21  b22  b23   0  ]
             [  0   b32  b33  b34 ]
             [  0    0   b43  b44 ]
     Unconstrained quadratic cost function J = SUM(e^T * Q * e + delta_u^T * R * delta_u)
     is solved via analytical gradient descent with dynamic slew-rate clamping and saturation.
====================================================================================================
*)

VAR_INPUT
    bEnable                     : BOOL;     (* Master Subsystem Enable / Execute Recipe *)
    bEmergencyStop              : BOOL;     (* Hardwired Safety Relay Circuit (Active-High Healthy) *)
    bPlatenSyncIndex            : BOOL;     (* Optical Tachometer Zero-Degree Platen Sync Pulse *)
    rPlatenSpeed_RPM            : REAL;     (* Platen Angular Rotational Velocity [rpm] *)
    rCarrierSpeed_RPM           : REAL;     (* Carrier Head Rotational Velocity [rpm] *)
    rEddySensor_ChA_mV          : REAL;     (* Demodulated Eddy Current Amplitude Channel A [mV] *)
    rEddySensor_ChB_mV          : REAL;     (* Demodulated Eddy Current Amplitude Channel B [mV] *)
    rEddySensor_ChC_mV          : REAL;     (* Demodulated Eddy Current Amplitude Channel C [mV] *)
    rEddyExcitationFreq_kHz     : REAL;     (* RF Resonant Bridge Excitation Frequency [kHz] *)
    rTargetFilmThickness_nm     : REAL;     (* Recipe Target Metal Film Endpoint Thickness [nm] *)
    rMaxZonePressure_psi        : REAL;     (* Upper Permissible Limit for Membrane Bladders [psi] *)
    rMinZonePressure_psi        : REAL;     (* Lower Permissible Limit for Membrane Bladders [psi] *)
    rPrestonCoeffNominal        : REAL;     (* Baseline Preston Removal Constant kp [nm/min/psi/(m/s)] *)
    rSlurryFlowRate_mlpm        : REAL;     (* Slurry Peristaltic Pump Flow Rate [ml/min] *)
    bResetFault                 : BOOL;     (* Supervisory Alarm Acknowledgement & Reset Command *)
END_VAR

VAR_OUTPUT
    bProcessActive              : BOOL;     (* Metrology & Closed-Loop Pressure Control Active *)
    bEndpointReached            : BOOL;     (* Wafer Metallization Clearance Endpoint Detected *)
    wSystemStatusWord           : WORD;     (* Packed Operational Status Bitfield *)
    wAlarmCodeWord              : WORD;     (* Diagnostic Fault & Hazard Bitfield *)
    rEstimatedThickness_nm      : REAL;     (* 2oo3 TMR Voted Current Wafer Thickness [nm] *)
    rRemovalRate_nm_min         : REAL;     (* Real-Time Differentiated Material Removal Rate [nm/min] *)
    rWIWNU_Percent              : REAL;     (* Instantaneous Within-Wafer Non-Uniformity Index [%] *)
    rPressureZone1_psi          : REAL;     (* Commanded Bladder Pressure - Zone 1 Center [psi] *)
    rPressureZone2_psi          : REAL;     (* Commanded Bladder Pressure - Zone 2 Middle-Inner [psi] *)
    rPressureZone3_psi          : REAL;     (* Commanded Bladder Pressure - Zone 3 Middle-Outer [psi] *)
    rPressureZone4_psi          : REAL;     (* Commanded Bladder Pressure - Zone 4 Wafer Edge [psi] *)
    rPressureRetainingRing_psi  : REAL;     (* Commanded Cylinder Force - Retaining Ring [psi] *)
    bDegradedMode               : BOOL;     (* Redundancy Degraded (Single Sensor Channel Discarded) *)
    bMembraneRuptureAlarm       : BOOL;     (* Pneumatic Circuit Mass-Flow Discrepancy Fault *)
END_VAR

VAR
    (* --- State Machine & Sequencing --- *)
    iState                      : INT := 0;      (* Main Finite State Machine Register *)
    iPrevState                  : INT := 0;      (* Historical State Register for Edge Detection *)
    tStateTimer                 : TON;           (* Generic State Dwell & Timeout Timer *)
    tSampleIntervalTimer        : TON;           (* Discrete 10ms Fast Metrology Execution Timer *)
    tEndpointDebounceTimer      : TON;           (* Optical & Eddy Endpoint Persistence Debounce *)

    (* --- Physical Sensor Processing & Calibration Constants --- *)
    rCal_A0                     : REAL := 12500.0; (* 3rd-Order Polynomial Coeff 0 [nm] *)
    rCal_A1                     : REAL := -8.452;  (* 3rd-Order Polynomial Coeff 1 [nm/mV] *)
    rCal_A2                     : REAL := 0.00287; (* 3rd-Order Polynomial Coeff 2 [nm/mV^2] *)
    rCal_A3                     : REAL := -0.00000045; (* 3rd-Order Polynomial Coeff 3 [nm/mV^3] *)
    rLiftOffRef_mV              : REAL := 120.0;   (* Free-Air Zero-Film Resonant Voltage [mV] *)
    rSkinDepth_um               : REAL := 0.0;     (* Calculated Skin Depth delta [micrometers] *)

    (* --- 2oo3 TMR Voting Internal Registers --- *)
    rThick_A_nm                 : REAL := 0.0;
    rThick_B_nm                 : REAL := 0.0;
    rThick_C_nm                 : REAL := 0.0;
    bChA_Valid                  : BOOL := TRUE;
    bChB_Valid                  : BOOL := TRUE;
    bChC_Valid                  : BOOL := TRUE;
    rDiscrepancy_AB             : REAL := 0.0;
    rDiscrepancy_BC             : REAL := 0.0;
    rDiscrepancy_CA             : REAL := 0.0;
    rTMR_Tolerance_nm           : REAL := 65.0;    (* Max Acceptable Channel Deviation [nm] *)

    (* --- Platen Radial Tracking & Zone Sampling --- *)
    bPlatenSync_Last            : BOOL := FALSE;   (* Previous Scan Sync Signal for Edge Triggers *)
    rRadialPosition_mm          : REAL := 0.0;     (* Sweep Head Current Wafer Radial Coordinate [mm] *)
    iZoneCurrent                : INT := 1;        (* Instantaneous Radial Zone (1=Center to 4=Edge) *)
    rZoneSum_Thick              : ARRAY[1..4] OF REAL := [0.0, 0.0, 0.0, 0.0];
    iZoneCount                  : ARRAY[1..4] OF DINT := [0, 0, 0, 0];
    rZoneFiltered_Thick_nm      : ARRAY[1..4] OF REAL := [1200.0, 1200.0, 1200.0, 1200.0];

    (* --- Model Predictive Control & State-Space Matrices --- *)
    (* Error vector x = Target - Current per Zone *)
    rError_Zone                 : ARRAY[1..4] OF REAL := [0.0, 0.0, 0.0, 0.0];
    (* B_d Coupling Matrix (pneumatic membrane cross-talk gains) *)
    rB_Coupling                 : ARRAY[1..4, 1..4] OF REAL := [
        [0.82, 0.18, 0.00, 0.00],
        [0.15, 0.70, 0.15, 0.00],
        [0.00, 0.16, 0.68, 0.16],
        [0.00, 0.00, 0.21, 0.79]
    ];
    (* MPC Tuning Weighting Matrices *)
    rDiagQ                      : ARRAY[1..4] OF REAL := [1.5, 1.2, 1.2, 2.0]; (* Error penalty *)
    rDiagR                      : ARRAY[1..4] OF REAL := [0.45, 0.45, 0.45, 0.60]; (* Slew penalty *)
    rDeltaPressure              : ARRAY[1..4] OF REAL := [0.0, 0.0, 0.0, 0.0];
    rCommandedPressure          : ARRAY[1..4] OF REAL := [3.2, 3.2, 3.2, 3.2]; (* Nominal [psi] *)
    rMaxSlewRate_psi_s          : REAL := 0.75;    (* Maximum Allowable Pressure Slew [psi/s] *)

    (* --- Filtering, Derivatives, & Metrology Calculations --- *)
    rThickPrev_nm               : REAL := 1200.0;
    rRawRemovalRate_nm_s        : REAL := 0.0;
    rFilteredMRR_nm_min         : REAL := 0.0;
    rMeanThick_nm               : REAL := 1200.0;
    rVariance_nm2               : REAL := 0.0;
    rStdDev_nm                  : REAL := 0.0;
    iIter                       : INT := 1;
    jIter                       : INT := 1;

    (* --- Constants --- *)
    CYCLE_TIME_SEC              : REAL := 0.010;   (* Deterministic Task Scan Period = 10 ms *)
    PI_CONST                    : REAL := 3.14159265;
    MIN_SLURRY_FLOW_MLPM        : REAL := 80.0;    (* Slurry Starvation Interlock Limit [ml/min] *)
    MIN_PLATEN_RPM              : REAL := 15.0;    (* Mechanical Stall Speed Interlock [rpm] *)
    OVERPOLISH_MARGIN_TIME      : TIME := T#4S;    (* Barrier Clearance Dwell Duration *)
END_VAR

(*
====================================================================================================
  EXECUTIVE LOGIC EXECUTION
====================================================================================================
*)

(* --- 1. HARDWIRED SAFETY INTERLOCKS AND SYSTEM TRIP CONDITIONS --- *)
IF NOT bEmergencyStop THEN
    (* Immediate De-energization of Pneumatic Regulator Chambers *)
    rPressureZone1_psi          := 0.0;
    rPressureZone2_psi          := 0.0;
    rPressureZone3_psi          := 0.0;
    rPressureZone4_psi          := 0.0;
    rPressureRetainingRing_psi  := 0.0;
    bProcessActive              := FALSE;
    bEndpointReached            := FALSE;
    wSystemStatusWord           := 16#0000;
    wAlarmCodeWord              := wAlarmCodeWord OR 16#0001; (* Bit 0: Emergency Stop Tripped *)
    iState                      := 99; (* EMERGENCY_ABORT *)
    RETURN;
END_IF;

(* Slurry Flow Rate Interlock to Protect Wafer & Pad from Dry Burnishing Friction *)
IF bEnable AND (rSlurryFlowRate_mlpm < MIN_SLURRY_FLOW_MLPM) AND (iState >= 20) AND (iState <= 50) THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0002; (* Bit 1: Slurry Starvation Hazard *)
    iState := 99;
END_IF;

(* Platen Kinematic Rotation Stall Interlock *)
IF bEnable AND (rPlatenSpeed_RPM < MIN_PLATEN_RPM) AND (iState >= 20) AND (iState <= 50) THEN
    wAlarmCodeWord := wAlarmCodeWord OR 16#0004; (* Bit 2: Platen Under-Speed Fault *)
    iState := 99;
END_IF;

(* Fault Reset Handler *)
IF bResetFault THEN
    wAlarmCodeWord := 16#0000;
    IF iState = 99 THEN
        iState := 0; (* Return to IDLE upon clean reset *)
    END_IF;
END_IF;

(* --- 2. HIGH-FREQUENCY EDDY CURRENT SIGNAL CONDITIONING & SKIN DEPTH --- *)
(* Calculate electromagnetic penetration skin depth: delta = sqrt(1 / (pi * f * mu * sigma)) *)
IF rEddyExcitationFreq_kHz > 10.0 THEN
    (* Simplified approximation for Copper at operating process temperature (35-45 deg C) *)
    rSkinDepth_um := 503.29 * SQRT( 1.72 / (rEddyExcitationFreq_kHz * 1000.0 * 1.0) );
ELSE
    rSkinDepth_um := 120.0;
END_IF;

(* Direct 3rd-Order Non-Linear Polynomial Impedance Conversion for Raw Channels *)
rThick_A_nm := rCal_A0 + (rCal_A1 * rEddySensor_ChA_mV) + 
               (rCal_A2 * rEddySensor_ChA_mV * rEddySensor_ChA_mV) + 
               (rCal_A3 * rEddySensor_ChA_mV * rEddySensor_ChA_mV * rEddySensor_ChA_mV);

rThick_B_nm := rCal_A0 + (rCal_A1 * rEddySensor_ChB_mV) + 
               (rCal_A2 * rEddySensor_ChB_mV * rEddySensor_ChB_mV) + 
               (rCal_A3 * rEddySensor_ChB_mV * rEddySensor_ChB_mV * rEddySensor_ChB_mV);

rThick_C_nm := rCal_A0 + (rCal_A1 * rEddySensor_ChC_mV) + 
               (rCal_A2 * rEddySensor_ChC_mV * rEddySensor_ChC_mV) + 
               (rCal_A3 * rEddySensor_ChC_mV * rEddySensor_ChC_mV * rEddySensor_ChC_mV);

(* Enforce non-negative boundary bounds on thickness computations *)
IF rThick_A_nm < 0.0 THEN rThick_A_nm := 0.0; END_IF;
IF rThick_B_nm < 0.0 THEN rThick_B_nm := 0.0; END_IF;
IF rThick_C_nm < 0.0 THEN rThick_C_nm := 0.0; END_IF;

(* --- 3. TRIPLE MODULAR REDUNDANCY (2oo3) VOTING AND FAULT ISOLATION --- *)
rDiscrepancy_AB := ABS(rThick_A_nm - rThick_B_nm);
rDiscrepancy_BC := ABS(rThick_B_nm - rThick_C_nm);
rDiscrepancy_CA := ABS(rThick_C_nm - rThick_A_nm);

bChA_Valid := TRUE;
bChB_Valid := TRUE;
bChC_Valid := TRUE;

IF (rDiscrepancy_AB <= rTMR_Tolerance_nm) AND (rDiscrepancy_BC <= rTMR_Tolerance_nm) AND (rDiscrepancy_CA <= rTMR_Tolerance_nm) THEN
    (* Case 3A: Complete Triplicate Consensus - Select Median Value *)
    bDegradedMode := FALSE;
    IF ((rThick_A_nm >= rThick_B_nm) AND (rThick_A_nm <= rThick_C_nm)) OR ((rThick_A_nm <= rThick_B_nm) AND (rThick_A_nm >= rThick_C_nm)) THEN
        rEstimatedThickness_nm := rThick_A_nm;
    ELSIF ((rThick_B_nm >= rThick_A_nm) AND (rThick_B_nm <= rThick_C_nm)) OR ((rThick_B_nm <= rThick_A_nm) AND (rThick_B_nm >= rThick_C_nm)) THEN
        rEstimatedThickness_nm := rThick_B_nm;
    ELSE
        rEstimatedThickness_nm := rThick_C_nm;
    END_IF;

ELSIF (rDiscrepancy_AB <= rTMR_Tolerance_nm) AND (rDiscrepancy_BC > rTMR_Tolerance_nm) AND (rDiscrepancy_CA > rTMR_Tolerance_nm) THEN
    (* Channel C deviates: ChA and ChB agree *)
    bChC_Valid := FALSE;
    bDegradedMode := TRUE;
    rEstimatedThickness_nm := (rThick_A_nm + rThick_B_nm) * 0.5;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0010; (* Bit 4: Eddy Sensor ChC Drift Fault *)

ELSIF (rDiscrepancy_BC <= rTMR_Tolerance_nm) AND (rDiscrepancy_AB > rTMR_Tolerance_nm) AND (rDiscrepancy_CA > rTMR_Tolerance_nm) THEN
    (* Channel A deviates: ChB and ChC agree *)
    bChA_Valid := FALSE;
    bDegradedMode := TRUE;
    rEstimatedThickness_nm := (rThick_B_nm + rThick_C_nm) * 0.5;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0020; (* Bit 5: Eddy Sensor ChA Drift Fault *)

ELSIF (rDiscrepancy_CA <= rTMR_Tolerance_nm) AND (rDiscrepancy_AB > rTMR_Tolerance_nm) AND (rDiscrepancy_BC > rTMR_Tolerance_nm) THEN
    (* Channel B deviates: ChA and ChC agree *)
    bChB_Valid := FALSE;
    bDegradedMode := TRUE;
    rEstimatedThickness_nm := (rThick_A_nm + rThick_C_nm) * 0.5;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0040; (* Bit 6: Eddy Sensor ChB Drift Fault *)

ELSE
    (* Triplicate Sensor Collapse: Multi-channel Disagreement Exceeds Safety Margin *)
    bChA_Valid := FALSE;
    bChB_Valid := FALSE;
    bChC_Valid := FALSE;
    bDegradedMode := TRUE;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0080; (* Bit 7: 2oo3 Sensor Voting Failure *)
    iState := 99; (* Trip to Safe Abort State *)
END_IF;

(* --- 4. PLATEN SYNCHRONIZATION AND RADIAL ZONE BINNING --- *)
(* Detect rising edge of platen zero-index optical sensor pulse *)
IF bPlatenSyncIndex AND NOT bPlatenSync_Last THEN
    (* Platen completed 360-degree rotation: Compute zonal averages and reset accumulators *)
    FOR iIter := 1 TO 4 DO
        IF iZoneCount[iIter] > 0 THEN
            rZoneFiltered_Thick_nm[iIter] := (0.75 * rZoneFiltered_Thick_nm[iIter]) + 
                                            (0.25 * (rZoneSum_Thick[iIter] / DINT_TO_REAL(iZoneCount[iIter])));
            rZoneSum_Thick[iIter] := 0.0;
            iZoneCount[iIter] := 0;
        END_IF;
    END_FOR;
    rRadialPosition_mm := 0.0;
END_IF;
bPlatenSync_Last := bPlatenSyncIndex;

(* Calculate sweep radial track across wafer based on platen angular velocity and scan period *)
IF rPlatenSpeed_RPM > 0.0 THEN
    rRadialPosition_mm := rRadialPosition_mm + ((rPlatenSpeed_RPM * 360.0 / 60.0) * CYCLE_TIME_SEC * 1.55);
    IF rRadialPosition_mm > 150.0 THEN
        rRadialPosition_mm := 150.0;
    END_IF;
END_IF;

(* Assign current measurement to wafer concentric annular zone *)
IF rRadialPosition_mm < 35.0 THEN
    iZoneCurrent := 1; (* Zone 1: Center [0 to 35mm] *)
ELSIF rRadialPosition_mm < 75.0 THEN
    iZoneCurrent := 2; (* Zone 2: Middle-Inner [35 to 75mm] *)
ELSIF rRadialPosition_mm < 125.0 THEN
    iZoneCurrent := 3; (* Zone 3: Middle-Outer [75 to 125mm] *)
ELSE
    iZoneCurrent := 4; (* Zone 4: Edge [125 to 150mm] *)
END_IF;

(* Accumulate measurements into corresponding zone bin *)
rZoneSum_Thick[iZoneCurrent] := rZoneSum_Thick[iZoneCurrent] + rEstimatedThickness_nm;
iZoneCount[iZoneCurrent] := iZoneCount[iZoneCurrent] + 1;

(* --- 5. WITHIN-WAFER NON-UNIFORMITY (WIWNU) & DERIVATIVE REMOVAL RATE --- *)
(* Calculate 4-Zone Mean Film Thickness *)
rMeanThick_nm := (rZoneFiltered_Thick_nm[1] + rZoneFiltered_Thick_nm[2] + 
                  rZoneFiltered_Thick_nm[3] + rZoneFiltered_Thick_nm[4]) * 0.25;

(* Calculate Spatial Variance *)
rVariance_nm2 := ((rZoneFiltered_Thick_nm[1] - rMeanThick_nm) * (rZoneFiltered_Thick_nm[1] - rMeanThick_nm) +
                  (rZoneFiltered_Thick_nm[2] - rMeanThick_nm) * (rZoneFiltered_Thick_nm[2] - rMeanThick_nm) +
                  (rZoneFiltered_Thick_nm[3] - rMeanThick_nm) * (rZoneFiltered_Thick_nm[3] - rMeanThick_nm) +
                  (rZoneFiltered_Thick_nm[4] - rMeanThick_nm) * (rZoneFiltered_Thick_nm[4] - rMeanThick_nm)) * 0.25;

IF rVariance_nm2 > 0.0001 THEN
    rStdDev_nm := SQRT(rVariance_nm2);
ELSE
    rStdDev_nm := 0.0;
END_IF;

(* WIWNU Percentage (1-Sigma relative to mean thickness) *)
IF rMeanThick_nm > 1.0 THEN
    rWIWNU_Percent := (rStdDev_nm / rMeanThick_nm) * 100.0;
ELSE
    rWIWNU_Percent := 0.0;
END_IF;

(* Low-pass filtered derivative for instantaneous Material Removal Rate (MRR) [nm/min] *)
rRawRemovalRate_nm_s := (rThickPrev_nm - rEstimatedThickness_nm) / CYCLE_TIME_SEC;
IF rRawRemovalRate_nm_s < 0.0 THEN
    rRawRemovalRate_nm_s := 0.0; (* Negative removal represents sensor noise / non-physical *)
END_IF;
rFilteredMRR_nm_min := (0.92 * rFilteredMRR_nm_min) + (0.08 * (rRawRemovalRate_nm_s * 60.0));
rRemovalRate_nm_min := rFilteredMRR_nm_min;
rThickPrev_nm := rEstimatedThickness_nm;

(* --- 6. MULTI-ZONE MODEL PREDICTIVE PRESSURE CONTROLLER (MPC) --- *)
(* Compute error vector: e_i = CurrentThickness_i - TargetThickness *)
FOR iIter := 1 TO 4 DO
    rError_Zone[iIter] := rZoneFiltered_Thick_nm[iIter] - rTargetFilmThickness_nm;
END_FOR;

(* Calculate decoupling matrix product and gradient descent step for zone pressure adjustments *)
FOR iIter := 1 TO 4 DO
    rDeltaPressure[iIter] := 0.0;
    FOR jIter := 1 TO 4 DO
        (* Unconstrained MPC gradient: DeltaP_i = Sum( (B_ij * Q_j * e_j) / (R_i + 0.1) ) * Scaling *)
        rDeltaPressure[iIter] := rDeltaPressure[iIter] + 
                                (rB_Coupling[jIter, iIter] * rDiagQ[jIter] * (rError_Zone[jIter] - (rMeanThick_nm - rTargetFilmThickness_nm))) / 
                                (rDiagR[iIter] + 1.0);
    END_FOR;
    (* Convert thickness error metric to delta-psi pressure increment *)
    rDeltaPressure[iIter] := rDeltaPressure[iIter] * 0.0018;

    (* Dynamic Slew-Rate Limiting per Scan *)
    IF rDeltaPressure[iIter] > (rMaxSlewRate_psi_s * CYCLE_TIME_SEC) THEN
        rDeltaPressure[iIter] := rMaxSlewRate_psi_s * CYCLE_TIME_SEC;
    ELSIF rDeltaPressure[iIter] < (-rMaxSlewRate_psi_s * CYCLE_TIME_SEC) THEN
        rDeltaPressure[iIter] := -rMaxSlewRate_psi_s * CYCLE_TIME_SEC;
    END_IF;
END_FOR;

(* --- 7. FINITE STATE MACHINE (FSM) SEQUENCER --- *)
CASE iState OF
    0: (* STATE: STANDBY_IDLE *)
        bProcessActive              := FALSE;
        bEndpointReached            := FALSE;
        rPressureZone1_psi          := 0.0;
        rPressureZone2_psi          := 0.0;
        rPressureZone3_psi          := 0.0;
        rPressureZone4_psi          := 0.0;
        rPressureRetainingRing_psi  := 0.0;
        wSystemStatusWord           := 16#0001; (* Idle Status *)

        IF bEnable AND (wAlarmCodeWord = 16#0000) THEN
            iState := 10;
        END_IF;

    10: (* STATE: OPTICAL_SYNC_ALIGN & BASELINE CALIBRATION *)
        bProcessActive              := TRUE;
        wSystemStatusWord           := 16#0002; (* Calibrating / Aligning *)
        rPressureZone1_psi          := 0.5;
        rPressureZone2_psi          := 0.5;
        rPressureZone3_psi          := 0.5;
        rPressureZone4_psi          := 0.5;
        rPressureRetainingRing_psi  := 1.2;

        tStateTimer(IN := TRUE, PT := T#3S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 20;
        END_IF;

    20: (* STATE: DOWNFORCE_RAMP & SLURRY COATING *)
        wSystemStatusWord           := 16#0004; (* Downforce Ramp *)
        rPressureZone1_psi          := 2.0;
        rPressureZone2_psi          := 2.0;
        rPressureZone3_psi          := 2.0;
        rPressureZone4_psi          := 2.0;
        rPressureRetainingRing_psi  := 3.0;

        tStateTimer(IN := TRUE, PT := T#2S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 30; (* Advance to closed-loop bulk polishing *)
        END_IF;

    30: (* STATE: BULK_POLISH_MPC - ACTIVE CLOSED LOOP NON-UNIFORMITY REGULATION *)
        wSystemStatusWord           := 16#0008; (* Active Bulk Polish *)

        (* Apply closed-loop MPC delta pressure to nominal base pressure (3.2 psi) *)
        rCommandedPressure[1] := 3.2 + rDeltaPressure[1];
        rCommandedPressure[2] := 3.2 + rDeltaPressure[2];
        rCommandedPressure[3] := 3.2 + rDeltaPressure[3];
        rCommandedPressure[4] := 3.2 + rDeltaPressure[4];

        (* Enforce Hard Actuator Saturation Limits *)
        FOR iIter := 1 TO 4 DO
            IF rCommandedPressure[iIter] > rMaxZonePressure_psi THEN
                rCommandedPressure[iIter] := rMaxZonePressure_psi;
            ELSIF rCommandedPressure[iIter] < rMinZonePressure_psi THEN
                rCommandedPressure[iIter] := rMinZonePressure_psi;
            END_IF;
        END_FOR;

        rPressureZone1_psi := rCommandedPressure[1];
        rPressureZone2_psi := rCommandedPressure[2];
        rPressureZone3_psi := rCommandedPressure[3];
        rPressureZone4_psi := rCommandedPressure[4];

        (* Dynamic Retaining Ring Pressure (1.35x Zone 4 edge pressure to prevent edge roll-off) *)
        rPressureRetainingRing_psi := rPressureZone4_psi * 1.35;
        IF rPressureRetainingRing_psi > (rMaxZonePressure_psi * 1.25) THEN
            rPressureRetainingRing_psi := rMaxZonePressure_psi * 1.25;
        END_IF;

        (* Soft-landing transition threshold: when thickness reaches 120 nm *)
        IF (rEstimatedThickness_nm <= (rTargetFilmThickness_nm + 70.0)) THEN
            iState := 40;
        END_IF;

    40: (* STATE: SOFT_LANDING_ENDPOINT_DETECT - REDUCED DOWNFORCE TO MITIGATE DISHING *)
        wSystemStatusWord           := 16#0010; (* Soft Landing & Endpoint Detection *)

        (* Scale down pressures to 1.4 psi to smoothly land on barrier layer *)
        rPressureZone1_psi          := 1.4 + (rDeltaPressure[1] * 0.4);
        rPressureZone2_psi          := 1.4 + (rDeltaPressure[2] * 0.4);
        rPressureZone3_psi          := 1.4 + (rDeltaPressure[3] * 0.4);
        rPressureZone4_psi          := 1.4 + (rDeltaPressure[4] * 0.4);
        rPressureRetainingRing_psi  := 2.0;

        (* Endpoint verification condition: Film thickness reaches target or clearance threshold *)
        tEndpointDebounceTimer(IN := (rEstimatedThickness_nm <= rTargetFilmThickness_nm), PT := T#500MS);
        IF tEndpointDebounceTimer.Q THEN
            tEndpointDebounceTimer(IN := FALSE);
            bEndpointReached := TRUE;
            iState := 50; (* Transition to Barrier Overpolish *)
        END_IF;

    50: (* STATE: OVERPOLISH_BARRIER - TA/TAN BARRIER REMOVAL BUFFER *)
        wSystemStatusWord           := 16#0020; (* Overpolish Dwell *)
        rPressureZone1_psi          := 1.0;
        rPressureZone2_psi          := 1.0;
        rPressureZone3_psi          := 1.0;
        rPressureZone4_psi          := 1.0;
        rPressureRetainingRing_psi  := 1.5;

        tStateTimer(IN := TRUE, PT := OVERPOLISH_MARGIN_TIME);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 60; (* Retract and de-energize *)
        END_IF;

    60: (* STATE: PRESSURE_RELIEF_RETRACT & WAFER DE-CHUCK *)
        wSystemStatusWord           := 16#0040; (* Wafer Retract / Chamber Purge *)
        rPressureZone1_psi          := 0.1;
        rPressureZone2_psi          := 0.1;
        rPressureZone3_psi          := 0.1;
        rPressureZone4_psi          := 0.1;
        rPressureRetainingRing_psi  := 0.2;

        tStateTimer(IN := TRUE, PT := T#2S);
        IF tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            bProcessActive := FALSE;
            iState := 0; (* Cycle Complete, return to Idle *)
        END_IF;

    99: (* STATE: EMERGENCY_DEGRADED_ABORT - FAIL-SAFE DE-PRESSURIZATION *)
        bProcessActive              := FALSE;
        rPressureZone1_psi          := 0.0;
        rPressureZone2_psi          := 0.0;
        rPressureZone3_psi          := 0.0;
        rPressureZone4_psi          := 0.0;
        rPressureRetainingRing_psi  := 0.0;
        wSystemStatusWord           := 16#8000; (* Fault Abort Active *)

        IF NOT bEnable THEN
            iState := 0;
        END_IF;

END_CASE;

(* --- 8. MEMBRANE RUPTURE & LEAKAGE MONITORING --- *)
(* If commanded pressure > 2.5 psi but estimated removal rate is 0 while rotating, suspect seal breach *)
IF (iState = 30) AND (rPressureZone1_psi > 2.5) AND (rFilteredMRR_nm_min < 5.0) AND (rPlatenSpeed_RPM > 30.0) THEN
    bMembraneRuptureAlarm := TRUE;
    wAlarmCodeWord := wAlarmCodeWord OR 16#0100; (* Bit 8: Membrane Chamber Rupture Warning *)
ELSE
    bMembraneRuptureAlarm := FALSE;
END_IF;

END_FUNCTION_BLOCK
